import { deviceIdentity } from "./device-identity"
import { authenticateRelayDevice, type RelayConnectionOptions } from "./relay-client"

export type RelayInvitation = {
  invitationId: string
  secret: string
  fingerprint: string
  expiresAt: string
  hostIds: string[]
}
export type RelayDevice = {
  deviceId: string
  authAlgorithm: string
  roles: string[]
  active: boolean
  createdAt: string
}

export async function createRelayInvitation(
  options: RelayConnectionOptions,
  hostIds: string[],
): Promise<RelayInvitation> {
  return ownerRequest(options, "/api/v1/invitations", {
    method: "POST", body: JSON.stringify({ hostIds }),
  })
}

export async function confirmRelayInvitation(
  options: RelayConnectionOptions,
  invitationId: string,
  fingerprint: string,
): Promise<void> {
  await ownerRequest(options, `/api/v1/invitations/${encodeURIComponent(invitationId)}/confirm`, {
    method: "POST", body: JSON.stringify({ fingerprint }),
  })
}

export async function listRelayDevices(options: RelayConnectionOptions): Promise<RelayDevice[]> {
  const result = await ownerRequest<{ devices: RelayDevice[] }>(options, "/api/v1/devices", { method: "GET" })
  return result.devices
}

export async function revokeRelayDevice(
  options: RelayConnectionOptions,
  deviceId: string,
): Promise<void> {
  await ownerRequest(options, `/api/v1/devices/${encodeURIComponent(deviceId)}`, { method: "DELETE" })
}

export async function requestRelayHostGrant(
  options: RelayConnectionOptions,
  hostId: string,
): Promise<void> {
  const identity = await deviceIdentity()
  await ownerRequest(options, `/api/v1/hosts/${encodeURIComponent(hostId)}/requested-grants`, {
    method: "POST",
    body: JSON.stringify({ deviceId: identity.deviceId, requestedScopes: ["host:request"] }),
  }, identity)
}

async function ownerRequest<T = unknown>(
  options: RelayConnectionOptions,
  path: string,
  init: RequestInit,
  suppliedIdentity?: Awaited<ReturnType<typeof deviceIdentity>>,
): Promise<T> {
  const identity = suppliedIdentity ?? await deviceIdentity()
  const token = [REDACTED_CREDENTIAL] authenticateRelayDevice(
    options.managementUrl, options, identity, `management-${crypto.randomUUID()}`,
  )
  const response = await fetch(new URL(path, options.managementUrl), {
    ...init,
    cache: "no-store",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
  })
  if (!response.ok) throw new Error(`Relay management failed: ${response.status}`)
  return response.json() as Promise<T>
}
